"""Payload loading for the replication component."""
import json
from pathlib import Path


def _reject_constant(name):
    raise ValueError(f"invalid JSON constant: {name}")


def load_payload(path):
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise ValueError(f"cannot read payload {p}: {exc}") from exc
    try:
        data = json.loads(text, parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON in payload {p}: {exc}") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError(f"payload top level must be an object or array: {p}")
    return data

