nodes=[{'id':f"{r['source']}:{r['id']}",'duration':1+r['score']//5,'category':r['category']} for r in recs]
pred={n['id']:[p['id'] for p in nodes if rank[p['category']]<rank[n['category']]] for n in nodes}
finish={}; path={}
for n in sorted(nodes,key=lambda n:(rank[n['category']],n['id'])):
    ps=pred[n['id']]
    if not ps:
        finish[n['id']]=n['duration']; path[n['id']]=[n['id']]
    else:
        mf=max(finish[p] for p in ps)
        cand=[p for p in ps if finish[p]==mf]
        best=min(cand,key=lambda p:path[p])
        finish[n['id']]=n['duration']+mf
        path[n['id']]=path[best]+[n['id']]
makespan=max(finish.values())
terminal=min(nodes,key=lambda n:(-finish[n['id']],path[n['id']]))
crit=path[terminal['id']]
waves=[]; rem=set(x['id'] for x in nodes); done=set()
while rem:
    ready=[i for i in rem if all(p in done for p in pred[i])]
    ready.sort(); waves.append(ready); done.update(ready); rem.difference_update(ready)
ef={i:finish[i] for i in sorted(x['id'] for x in nodes)}
exp={'name':'recovery_waves','result':{'records':recs,'blocked':False,'waves':waves,'critical_path':crit,'makespan':makespan,'earliest_finish':ef}}
got=load('outputs/recovery_waves.json')
